'use client'

import { useEffect, useRef } from 'react'

const particles = Array.from({ length: 55 }, (_, i) => ({
  id: i,
  left: `${(i * 37.7) % 100}%`,
  top: `${(i * 61.3) % 100}%`,
  size: 1 + (i % 3) * 0.5,
  delay: `${(i % 9) * 0.6}s`,
  duration: `${7 + (i % 7)}s`,
}))

export function ForensicBackground() {
  const glowRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const handleMouseMove = (event: MouseEvent) => {
      if (!glowRef.current) return

      const x = event.clientX
      const y = event.clientY

      glowRef.current.style.transform = `translate3d(${x}px, ${y}px, 0)`
    }

    window.addEventListener('mousemove', handleMouseMove)

    return () => {
      window.removeEventListener('mousemove', handleMouseMove)
    }
  }, [])

  return (
    <>
      <style jsx>{`
        @keyframes particleFloat {
          0%,
          100% {
            transform: translate3d(0, 0, 0) scale(0.7);
            opacity: 0.12;
          }

          25% {
            transform: translate3d(8px, -14px, 0) scale(1);
            opacity: 0.55;
          }

          50% {
            transform: translate3d(-5px, -25px, 0) scale(1.25);
            opacity: 0.85;
          }

          75% {
            transform: translate3d(-12px, -8px, 0) scale(0.9);
            opacity: 0.4;
          }
        }

        @keyframes scanHorizontal {
          0% {
            transform: translateY(-20vh);
            opacity: 0;
          }

          10% {
            opacity: 0.35;
          }

          50% {
            opacity: 0.12;
          }

          90% {
            opacity: 0.3;
          }

          100% {
            transform: translateY(120vh);
            opacity: 0;
          }
        }

        @keyframes scanVertical {
          0% {
            transform: translateX(-20vw);
            opacity: 0;
          }

          15% {
            opacity: 0.25;
          }

          50% {
            opacity: 0.08;
          }

          85% {
            opacity: 0.2;
          }

          100% {
            transform: translateX(120vw);
            opacity: 0;
          }
        }

        @keyframes dataWave {
          0% {
            transform: translateX(-20%);
            opacity: 0;
          }

          20% {
            opacity: 0.12;
          }

          50% {
            opacity: 0.3;
          }

          80% {
            opacity: 0.1;
          }

          100% {
            transform: translateX(20%);
            opacity: 0;
          }
        }

        @keyframes pulseRing {
          0% {
            transform: scale(0.85);
            opacity: 0.25;
          }

          70% {
            transform: scale(1.35);
            opacity: 0;
          }

          100% {
            transform: scale(1.35);
            opacity: 0;
          }
        }

        @keyframes gridShift {
          from {
            background-position: 0 0;
          }

          to {
            background-position: 45px 45px;
          }
        }

        .forensic-particle {
          animation: particleFloat var(--duration) ease-in-out infinite;
          animation-delay: var(--delay);
        }

        .forensic-scan-horizontal {
          animation: scanHorizontal 11s linear infinite;
        }

        .forensic-scan-vertical {
          animation: scanVertical 17s linear infinite;
        }

        .forensic-wave {
          animation: dataWave 9s ease-in-out infinite;
        }

        .forensic-ring {
          animation: pulseRing 5s ease-out infinite;
        }

        .forensic-grid {
          animation: gridShift 18s linear infinite;
        }

        @media (prefers-reduced-motion: reduce) {
          .forensic-particle,
          .forensic-scan-horizontal,
          .forensic-scan-vertical,
          .forensic-wave,
          .forensic-ring,
          .forensic-grid {
            animation: none;
          }
        }
      `}</style>

      <div
        aria-hidden="true"
        className="pointer-events-none fixed inset-0 z-0 overflow-hidden"
      >
        {/* Deep atmospheric glow */}

        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_-10%,rgba(0,180,255,0.09),transparent_35%),radial-gradient(circle_at_90%_80%,rgba(0,255,170,0.055),transparent_30%),radial-gradient(circle_at_10%_70%,rgba(40,100,255,0.045),transparent_30%)]" />

        {/* Animated technical grid */}

        <div
          className="forensic-grid absolute inset-0 opacity-[0.18]"
          style={{
            backgroundImage: `
              linear-gradient(rgba(100,180,255,0.10) 1px, transparent 1px),
              linear-gradient(90deg, rgba(100,180,255,0.10) 1px, transparent 1px)
            `,
            backgroundSize: '45px 45px',
            maskImage:
              'radial-gradient(ellipse at center, black 25%, transparent 85%)',
            WebkitMaskImage:
              'radial-gradient(ellipse at center, black 25%, transparent 85%)',
          }}
        />

        {/* Secondary micro grid */}

        <div
          className="absolute inset-0 opacity-[0.09]"
          style={{
            backgroundImage: `
              linear-gradient(rgba(255,255,255,0.07) 1px, transparent 1px),
              linear-gradient(90deg, rgba(255,255,255,0.07) 1px, transparent 1px)
            `,
            backgroundSize: '9px 9px',
            maskImage:
              'radial-gradient(ellipse at center, black 0%, transparent 72%)',
            WebkitMaskImage:
              'radial-gradient(ellipse at center, black 0%, transparent 72%)',
          }}
        />

        {/* Mouse-following spotlight */}

        <div
          ref={glowRef}
          className="absolute left-0 top-0 size-[360px] -translate-x-1/2 -translate-y-1/2 rounded-full opacity-[0.12] blur-3xl"
          style={{
            background:
              'radial-gradient(circle, rgba(0,210,255,0.75) 0%, rgba(0,210,255,0.25) 30%, transparent 70%)',
            willChange: 'transform',
          }}
        />

        {/* Ambient investigation nodes */}

        <div className="absolute left-[12%] top-[28%] size-44 rounded-full border border-primary/[0.08]">

          <div className="forensic-ring absolute inset-0 rounded-full border border-primary/[0.15]" />

          <div className="absolute left-1/2 top-1/2 size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary shadow-[0_0_14px_var(--primary)]" />

        </div>

        <div
          className="absolute right-[14%] top-[62%] size-64 rounded-full border border-success/[0.06]"
        >

          <div
            className="forensic-ring absolute inset-0 rounded-full border border-success/[0.12]"
            style={{ animationDelay: '1.7s' }}
          />

          <div className="absolute left-1/2 top-1/2 size-1 rounded-full bg-success shadow-[0_0_12px_var(--success)]" />

        </div>

        {/* Floating particles */}

        {particles.map((particle) => (
          <span
            key={particle.id}
            className="forensic-particle absolute rounded-full bg-primary"
            style={
              {
                left: particle.left,
                top: particle.top,
                width: `${particle.size}px`,
                height: `${particle.size}px`,
                '--delay': particle.delay,
                '--duration': particle.duration,
                boxShadow:
                  '0 0 5px rgba(0,210,255,0.7), 0 0 12px rgba(0,210,255,0.2)',
              } as React.CSSProperties
            }
          />
        ))}

        {/* Horizontal forensic scan */}

        <div className="forensic-scan-horizontal absolute left-0 top-0 h-px w-full bg-gradient-to-r from-transparent via-primary/35 to-transparent shadow-[0_0_12px_rgba(0,210,255,0.3)]" />

        {/* Vertical scan */}

        <div className="forensic-scan-vertical absolute left-0 top-0 h-full w-px bg-gradient-to-b from-transparent via-primary/20 to-transparent" />

        {/* Bottom data waves */}

        <svg
          className="forensic-wave absolute bottom-[-30px] left-[-10%] h-52 w-[120%] opacity-30"
          viewBox="0 0 1200 220"
          preserveAspectRatio="none"
        >
          <path
            d="M0 150 C120 80 190 190 320 125 S520 55 650 135 S860 195 1000 105 S1120 80 1200 120"
            fill="none"
            stroke="currentColor"
            strokeOpacity="0.3"
            strokeWidth="1"
          />

          <path
            d="M0 180 C150 110 220 210 360 145 S550 85 700 160 S890 210 1040 130 S1140 110 1200 140"
            fill="none"
            stroke="currentColor"
            strokeOpacity="0.18"
            strokeWidth="1"
          />
        </svg>

        {/* Vignette */}

        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_35%,rgba(0,0,0,0.28)_100%)]" />
      </div>
    </>
  )
}